 const today=new Date(),date=field('ideasDate','Day','date',[today.getFullYear(),String(today.getMonth()+1).padStart(2,'0'),String(today.getDate()).padStart(2,'0')].join('-')),from=field('ideasFrom','From','time','09:00'),to=field('ideasTo','Until','time','21:00');
